@Test
    public void testReadWithOffsetAndLength() throws IOException {
        byte[] data = new byte[]{0, 1, 2, 3, 4, 5};
        CRC32 crc32 = new CRC32();
        crc32.update(data);
        InputStream in = new ByteArrayInputStream(data);

        try (ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(crc32, in)) {
            byte[] buffer = new byte[10];
            int read = cis.read(buffer, 2, 3); // read 2, 3, 4
            assertEquals(3, read);
            assertEquals(2, buffer[2]);
            assertEquals(3, buffer[3]);
            assertEquals(4, buffer[4]);

            assertEquals(crc32.getValue(), cis.getValue());
        }
    }

