        CharSequenceTranslator translator = new TestTranslator(2, "HAPPY");
        StringWriter writer = new StringWriter();
        String input = "A\uD83D\uDE00B"; 
        translator.translate(input, writer);
        // A + HAPPY + B
        assertEquals("AHAPPYB", writer.toString());
    }

