@Test
    public void testReadWithOffsetAndLength() throws IOException {
        byte[] data = {10, 20, 30, 40, 50};
        InputStream in = new ByteArrayInputStream(data);
        CRC32 crc32 = new CRC32();
        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(crc32, in);

        byte[] buffer = new byte[5];
        int read = cis.read(buffer, 1, 2); // read 30 and 40 into buffer[1] and buffer[2]

        assertEquals(2, read);
        assertEquals(30, buffer[1]);
        assertEquals(40, buffer[2]);

        CRC32 expectedCrc = new CRC32();
        expectedCrc.update(new byte[]{10, 20, 30, 40});
        assertEquals(expectedCrc.getValue(), crc32.getValue());
    }

