@Test
    public void testGetNextTarEntry_MultipleEntriesWithSkip() throws IOException {
        byte[] h1 = createTarHeader("file1.txt", 2);
        byte[] c1 = "ab".getBytes();
        byte[] h2 = createTarHeader("file2.txt", 3);
        byte[] c2 = "cde".getBytes();

        ByteBuffer buffer = ByteBuffer.allocate(h1.length + c1.length + h2.length + c2.length);
        buffer.put(h1).put(c1).put(h2).put(c2);

        TarArchiveInputStream tais = new TarArchiveInputStream(new ByteArrayInputStream(buffer.array()));

        // First entry
        TarArchiveEntry e1 = tais.getNextTarEntry();
        Assert.assertNotNull(e1);
        Assert.assertEquals("file1.txt", e1.getName());

        // Second entry (this triggers the 'if (currEntry != null)' block to skip c1)
        TarArchiveEntry e2 = tais.getNextTarEntry();
        Assert.assertNotNull(e2);
        Assert.assertEquals("file2.txt", e2.getName());

        byte[] readBuf = new byte[3];
        tais.read(readBuf);
        Assert.assertArrayEquals("cde".getBytes(), readBuf);
    }

